/**
 * Grouping (S8: GRP-1..8, DSH-8, D-072, D-073).
 *
 * - Saved arrangements (`group_templates`) per class+subject: five defaults on first use (GRP-1),
 *   generated by the pure solver (domain/grouping.ts) from the roster, the subject levels (S2,
 *   `student_subject_levels`) and the pair rules; editable by hand (moves, names, roles), saved as new
 *   arrangements, archived instead of deleted (GRP-2/3/6).
 * - Pair rules are private teacher data (GRP-4/7). Broken rules are stored and shown in the teacher
 *   area with a reason (GRP-8).
 * - Using an arrangement in a lesson copies it into `lesson_groupings`, fitted to the students who
 *   are not absent; the saved arrangement never changes (GRP-5).
 * - The classroom only ever receives group names, icons, members (classroom-safe fields) and roles,
 *   plus counts (GRP-7).
 */
import { and, asc, eq, gte, inArray, isNull, lte } from 'drizzle-orm';
import type { z } from 'zod';
import { effectiveAttendance, isAway } from '../../../domain/attendance.ts';
import { evaluateRules, fitToPresent, levelRanks, solveGroups, type PairRule as DomainRule } from '../../../domain/grouping.ts';
import type * as C from '../../../shared/contracts/grouping.ts';
import {
  DEFAULT_ARRANGEMENTS,
  groupName,
  type GroupInput,
  type GroupTemplate,
  type GroupingLessonState,
  type GroupingMode,
  type GroupingOverview,
  type PairRule,
  type Sizing,
} from '../../../shared/contracts/grouping.ts';
import type { LocalizedTextValue } from '../../../shared/contracts/define.ts';
import { initials, normaliseName } from '../../../shared/text/turkish.ts';
import { tx, type Db } from '../../db/client.ts';
import { groupTemplates, lessonGroupings, lessons, pairConstraints, studentSubjectLevels, students, type GroupJson, type UnsatisfiedJson } from '../../db/schema.ts';
import { audit } from '../../lib/audit.ts';
import type { CommandMeta } from '../../lib/commands.ts';
import { requireUser, type RequestContext } from '../../lib/context.ts';
import { newId } from '../../lib/crypto.ts';
import { AppError, notFound } from '../../lib/errors.ts';
import { dailyFor, exceptionsFor } from '../attendance/service.ts';
import type { LessonRow } from '../lessons/endSteps.ts';
import { lessonForCommand, updateLesson } from '../lessons/service.ts';
import { assertModuleEnabled, isModuleEnabled, moduleConfig } from '../school/modules.ts';
import { assertClassWritable, assertOwnsContext, getClass, getYear, todayFor, type ClassRow, type ContextRow } from '../school/policy.ts';
import { rosterRowsOn, type StudentRow } from '../students/service.ts';

type In<T extends { input: z.ZodType }> = z.infer<T['input']>;
type TemplateRow = typeof groupTemplates.$inferSelect;
type RuleRow = typeof pairConstraints.$inferSelect;

const isWritable = (db: Db, cls: ClassRow) => !cls.archivedAt && !getYear(db, cls.schoolYearId).archivedAt;

// ---------------------------------------------------------------- inputs to the solver
function rosterOn(db: Db, cls: ClassRow, date: string): StudentRow[] {
  return rosterRowsOn(db, cls.id, date).map((r) => r.student);
}

/** Subject levels (teacher data, GRP-3) for these students: free text, null when not assessed. */
function levelsOf(db: Db, subjectId: string, ids: readonly string[]): Map<string, string | null> {
  const rows = ids.length
    ? db.select().from(studentSubjectLevels).where(and(eq(studentSubjectLevels.subjectId, subjectId), inArray(studentSubjectLevels.studentId, [...ids]))).all()
    : [];
  const by = new Map(rows.map((r) => [r.studentId, r.level]));
  return new Map(ids.map((id) => [id, by.get(id) ?? null]));
}

function ruleRows(db: Db, contextId: string): RuleRow[] {
  return db.select().from(pairConstraints).where(and(eq(pairConstraints.contextId, contextId), isNull(pairConstraints.archivedAt))).orderBy(asc(pairConstraints.createdAt)).all();
}
const domainRules = (rows: readonly RuleRow[]): DomainRule[] => rows.map((r) => ({ id: r.id, a: r.studentA, b: r.studentB, kind: r.kind }));

/** Group n+1: a neutral "Group N" with a number badge (S13a: the cards show 'Group N' + icon + count). */
const defaultName = (i: number) => ({ name: groupName(i + 1), icon: `g${i + 1}` });

/** Groups for `mode` + `sizing`, keeping the names and icons of `previous` groups by position. */
function generateGroups(ctx: RequestContext, context: ContextRow, mode: Exclude<GroupingMode, 'custom'>, sizing: Sizing, seed: string, previous: readonly GroupJson[] = []) {
  const cls = getClass(ctx.db, context.classId);
  return generateFor(ctx.db, context, rosterOn(ctx.db, cls, todayFor(ctx, cls)), mode, sizing, seed, previous);
}

function generateFor(db: Db, context: ContextRow, roster: readonly StudentRow[], mode: Exclude<GroupingMode, 'custom'>, sizing: Sizing, seed: string, previous: readonly GroupJson[]) {
  const ranks = levelRanks(levelsOf(db, context.subjectId, roster.map((s) => s.id)));
  const result = solveGroups({ students: roster.map((s) => ({ id: s.id, levelRank: ranks.get(s.id) ?? null })), mode, sizing, rules: domainRules(ruleRows(db, context.id)), seed });
  const groups: GroupJson[] = result.groups.map((memberIds, i) => {
    const prev = previous[i];
    const d = defaultName(i);
    return { id: prev?.id ?? newId(), name: prev?.name ?? { ...d.name }, icon: prev?.icon ?? d.icon, memberIds, roles: [] };
  });
  return { groups, unsatisfied: result.unsatisfied as UnsatisfiedJson[] };
}

// ---------------------------------------------------------------- DTOs
const toTemplate = (r: TemplateRow): GroupTemplate => ({
  id: r.id,
  name: r.name,
  mode: r.mode,
  sizing: r.sizingJson,
  seed: r.seed,
  version: r.version,
  groups: r.groupsJson,
  unsatisfied: r.unsatisfiedJson as GroupTemplate['unsatisfied'],
  defaultKey: r.defaultKey,
  icon: (r.icon as GroupTemplate['icon']) ?? null,
  archived: r.archivedAt !== null,
  updatedAt: r.updatedAt,
});
const toRule = (r: RuleRow): PairRule => ({ id: r.id, studentA: r.studentA, studentB: r.studentB, kind: r.kind, note: r.note, updatedAt: r.updatedAt });

function templateRows(db: Db, contextId: string, includeArchived: boolean): TemplateRow[] {
  const rows = db.select().from(groupTemplates).where(eq(groupTemplates.contextId, contextId)).orderBy(asc(groupTemplates.sortOrder), asc(groupTemplates.createdAt)).all();
  return includeArchived ? rows : rows.filter((r) => r.archivedAt === null);
}

// ---------------------------------------------------------------- defaults (GRP-1)
/**
 * The five default arrangements, created once per class+subject: only while the context has no
 * arrangement row at all, so an archived or edited default is never recreated (D-072). Nothing is
 * written in an archived class or school year (DAT-1), and nothing while the class has no students
 * yet (the defaults would have no groups). A default that was saved without any member (made before
 * this rule) is generated again, keeping its names, once the class has students.
 */
export function ensureDefaultArrangements(ctx: RequestContext, context: ContextRow): void {
  const cls = getClass(ctx.db, context.classId);
  if (!isWritable(ctx.db, cls)) return;
  tx(ctx.db, () => {
    const roster = rosterOn(ctx.db, cls, todayFor(ctx, cls));
    if (!roster.length) return;
    const rows = templateRows(ctx.db, context.id, true);
    if (rows.length) {
      for (const row of rows) {
        if (row.defaultKey === null || row.mode === 'custom' || row.archivedAt !== null || row.groupsJson.some((g) => g.memberIds.length > 0)) continue;
        const { groups, unsatisfied } = generateFor(ctx.db, context, roster, row.mode, row.sizingJson, row.seed, row.groupsJson);
        ctx.db.update(groupTemplates).set({ groupsJson: groups, unsatisfiedJson: unsatisfied, version: row.version + 1, updatedAt: ctx.now() }).where(eq(groupTemplates.id, row.id)).run();
        audit(ctx.db, ctx.actor, { action: 'grouping.defaults_filled', entity: 'group_template', entityId: row.id, after: { groups: groups.length } }, ctx.now());
      }
      return;
    }
    insertDefaults(ctx, context, roster, 0);
  });
}

/** The four default options (GRP-1 as changed in S13a, D-098), after `sortFrom` existing rows. */
function insertDefaults(ctx: RequestContext, context: ContextRow, roster: readonly StudentRow[], sortFrom: number): void {
  const now = ctx.now();
  DEFAULT_ARRANGEMENTS.forEach((d, j) => {
    const i = sortFrom + j;
    const seed = `${context.id}:${d.key}`;
    const { groups, unsatisfied } = generateFor(ctx.db, context, roster, d.mode, d.sizing, seed, []);
    ctx.db
      .insert(groupTemplates)
      .values({ id: newId(), contextId: context.id, name: { ...d.name }, mode: d.mode, sizingJson: d.sizing, seed, version: 1, groupsJson: groups, unsatisfiedJson: unsatisfied, defaultKey: d.key, icon: d.icon, sortOrder: i, archivedAt: null, createdAt: now, createdBy: ctx.user?.id ?? null, updatedAt: now, updatedBy: ctx.user?.id ?? null })
      .run();
  });
  audit(ctx.db, ctx.actor, { action: 'grouping.defaults_created', entity: 'teaching_context', entityId: context.id, after: { count: DEFAULT_ARRANGEMENTS.length } }, now);
}

const NEW_DEFAULT_KEYS = new Set<string>(DEFAULT_ARRANGEMENTS.map((d) => d.key));
const usesNewDefaults = (rows: readonly TemplateRow[]) => rows.some((r) => r.defaultKey !== null && NEW_DEFAULT_KEYS.has(r.defaultKey));

/**
 * "Use the 4 default options" (D-098): the context's current arrangements are archived (kept as
 * history, restorable, lessons keep referring to them) and the four default options are created.
 * Refused when the context already has them.
 */
export function useDefaultOptions(ctx: RequestContext, contextId: string): GroupingOverview {
  tx(ctx.db, () => {
    const context = assertOwnsContext(ctx, contextId);
    const cls = getClass(ctx.db, context.classId);
    assertClassWritable(ctx.db, cls);
    assertModuleEnabled(ctx.db, context.id, 'grouping');
    const rows = templateRows(ctx.db, context.id, true);
    if (usesNewDefaults(rows)) throw new AppError('CONFLICT', 'The default options are already there', { reason: 'DEFAULTS_ALREADY_USED' });
    const now = ctx.now();
    const archived = rows.filter((r) => r.archivedAt === null);
    for (const r of archived) ctx.db.update(groupTemplates).set({ archivedAt: now, updatedAt: now, updatedBy: requireUser(ctx).id, version: r.version + 1 }).where(eq(groupTemplates.id, r.id)).run();
    audit(ctx.db, ctx.actor, { action: 'grouping.use_defaults', entity: 'teaching_context', entityId: context.id, after: { archived: archived.length } }, now);
    insertDefaults(ctx, context, rosterOn(ctx.db, cls, todayFor(ctx, cls)), rows.reduce((m, r) => Math.max(m, r.sortOrder), -1) + 1);
  });
  return overview(ctx, contextId, false);
}

// ---------------------------------------------------------------- teacher area
export function overview(ctx: RequestContext, contextId: string, includeArchived: boolean): GroupingOverview {
  const context = assertOwnsContext(ctx, contextId);
  if (isModuleEnabled(ctx.db, context.id, 'grouping')) ensureDefaultArrangements(ctx, context);
  const cls = getClass(ctx.db, context.classId);
  const roster = rosterOn(ctx.db, cls, todayFor(ctx, cls));
  const levels = levelsOf(ctx.db, context.subjectId, roster.map((s) => s.id));
  return {
    contextId: context.id,
    canUseNewDefaults: !usesNewDefaults(templateRows(ctx.db, context.id, true)),
    templates: templateRows(ctx.db, context.id, includeArchived).map(toTemplate),
    students: roster.map((s) => ({ id: s.id, fullName: s.fullName, initials: initials(s.fullName), avatarHue: s.avatarHue, level: levels.get(s.id) ?? null })),
    rules: ruleRows(ctx.db, context.id).map(toRule),
  };
}

/** The context of an arrangement the teacher owns (ACC-10), writable class, module on. */
function ownedTemplate(ctx: RequestContext, templateId: string, write: boolean) {
  const row = ctx.db.select().from(groupTemplates).where(eq(groupTemplates.id, templateId)).get();
  if (!row) throw notFound('Arrangement');
  const context = assertOwnsContext(ctx, row.contextId);
  if (write) {
    assertClassWritable(ctx.db, getClass(ctx.db, context.classId));
    assertModuleEnabled(ctx.db, context.id, 'grouping');
  }
  return { row, context };
}

const cleanText = (t: LocalizedTextValue): LocalizedTextValue => ({ ...(t.en?.trim() ? { en: normaliseName(t.en) } : {}), ...(t.tr?.trim() ? { tr: normaliseName(t.tr) } : {}) });

/**
 * Hand-made groups: every member is a current student of the class, at most once (GRP-3). Students
 * of the saved arrangement who have since left the class are dropped (so an older arrangement stays
 * editable even from a stale screen); any other student outside the class is refused.
 */
function groupsFromInput(ctx: RequestContext, context: ContextRow, input: readonly GroupInput[], previous: readonly GroupJson[]): GroupJson[] {
  const cls = getClass(ctx.db, context.classId);
  const roster = new Set(rosterOn(ctx.db, cls, todayFor(ctx, cls)).map((s) => s.id));
  const left = new Set(previous.flatMap((g) => g.memberIds).filter((id) => !roster.has(id)));
  const seen = new Set<string>();
  const prevIds = new Set(previous.map((g) => g.id));
  return input.map((g, i) => {
    const memberIds = g.memberIds.filter((id) => !left.has(id));
    for (const id of memberIds) {
      if (!roster.has(id)) throw new AppError('VALIDATION', 'Student is not in this class', { reason: 'STUDENT_NOT_IN_CLASS' });
      if (seen.has(id)) throw new AppError('VALIDATION', 'A student can be in one group only', { reason: 'STUDENT_IN_TWO_GROUPS' });
      seen.add(id);
    }
    const members = new Set(memberIds);
    const roles = (g.roles ?? []).filter((r) => members.has(r.studentId) && (r.label.en?.trim() || r.label.tr?.trim())).map((r) => ({ studentId: r.studentId, label: cleanText(r.label) }));
    return { id: g.id && prevIds.has(g.id) ? g.id : newId(), name: cleanText(g.name), icon: g.icon ?? defaultName(i).icon, memberIds, roles };
  });
}

export function createTemplate(ctx: RequestContext, input: In<typeof C.createGroupTemplate>): GroupTemplate {
  return tx(ctx.db, () => {
    const context = assertOwnsContext(ctx, input.contextId);
    assertClassWritable(ctx.db, getClass(ctx.db, context.classId));
    assertModuleEnabled(ctx.db, context.id, 'grouping');
    ensureDefaultArrangements(ctx, context);
    const now = ctx.now();
    const seed = newId();
    let groups: GroupJson[];
    let unsatisfied: UnsatisfiedJson[];
    if (input.mode === 'custom') {
      if (!input.groups?.length) throw new AppError('VALIDATION', 'Hand-made arrangements need groups', { reason: 'GROUPS_REQUIRED' });
      groups = groupsFromInput(ctx, context, input.groups, []);
      unsatisfied = evaluateRules(groups.map((g) => g.memberIds), domainRules(ruleRows(ctx.db, context.id)), { byHand: true }) as UnsatisfiedJson[];
    } else ({ groups, unsatisfied } = generateGroups(ctx, context, input.mode, input.sizing, seed));
    const last = templateRows(ctx.db, context.id, true).reduce((m, r) => Math.max(m, r.sortOrder), -1);
    const id = newId();
    ctx.db
      .insert(groupTemplates)
      .values({ id, contextId: context.id, name: cleanText(input.name), mode: input.mode, sizingJson: input.sizing, seed, version: 1, groupsJson: groups, unsatisfiedJson: unsatisfied, defaultKey: null, icon: input.icon ?? null, sortOrder: last + 1, archivedAt: null, createdAt: now, createdBy: requireUser(ctx).id, updatedAt: now, updatedBy: requireUser(ctx).id })
      .run();
    audit(ctx.db, ctx.actor, { action: 'grouping.template_create', entity: 'group_template', entityId: id, after: { name: input.name, mode: input.mode, sizing: input.sizing, groups: groups.length } }, now);
    return toTemplate(ctx.db.select().from(groupTemplates).where(eq(groupTemplates.id, id)).get()!);
  });
}

function assertVersion(row: TemplateRow, expected: number) {
  if (row.version !== expected) throw new AppError('CONFLICT', 'The arrangement was changed in the meantime', { reason: 'VERSION_CONFLICT', version: row.version });
}

function saveTemplate(ctx: RequestContext, row: TemplateRow, patch: Partial<TemplateRow>, action: string, before: unknown, after: unknown): GroupTemplate {
  const now = ctx.now();
  ctx.db
    .update(groupTemplates)
    .set({ ...patch, version: row.version + 1, updatedAt: now, updatedBy: requireUser(ctx).id })
    .where(eq(groupTemplates.id, row.id))
    .run();
  audit(ctx.db, ctx.actor, { action, entity: 'group_template', entityId: row.id, before, after }, now);
  return toTemplate(ctx.db.select().from(groupTemplates).where(eq(groupTemplates.id, row.id)).get()!);
}

export function generateTemplate(ctx: RequestContext, input: In<typeof C.generateGroupTemplate>): GroupTemplate {
  return tx(ctx.db, () => {
    const { row, context } = ownedTemplate(ctx, input.templateId, true);
    assertVersion(row, input.expectedVersion);
    const mode = row.mode === 'custom' ? 'mixed' : row.mode;
    const seed = input.seed ?? newId();
    const { groups, unsatisfied } = generateGroups(ctx, context, mode, row.sizingJson, seed, row.groupsJson);
    return saveTemplate(ctx, row, { mode, seed, groupsJson: groups, unsatisfiedJson: unsatisfied }, 'grouping.template_generate', { version: row.version, groups: row.groupsJson.map((g) => g.memberIds) }, { groups: groups.map((g) => g.memberIds) });
  });
}

export function updateTemplate(ctx: RequestContext, input: In<typeof C.updateGroupTemplate>): GroupTemplate {
  return tx(ctx.db, () => {
    const { row, context } = ownedTemplate(ctx, input.templateId, true);
    assertVersion(row, input.expectedVersion);
    const patch: Partial<TemplateRow> = {};
    if (input.name) patch.name = cleanText(input.name);
    if (input.icon !== undefined) patch.icon = input.icon;
    const mode = input.mode ?? row.mode;
    const sizing = input.sizing ?? row.sizingJson;
    patch.mode = mode;
    patch.sizingJson = sizing;
    if (input.groups) {
      patch.groupsJson = groupsFromInput(ctx, context, input.groups, row.groupsJson);
      patch.unsatisfiedJson = evaluateRules(patch.groupsJson.map((g) => g.memberIds), domainRules(ruleRows(ctx.db, context.id)), { byHand: true }) as UnsatisfiedJson[];
    } else if ((input.mode && input.mode !== row.mode) || (input.sizing && JSON.stringify(input.sizing) !== JSON.stringify(row.sizingJson))) {
      if (mode === 'custom') throw new AppError('VALIDATION', 'Hand-made arrangements need groups', { reason: 'GROUPS_REQUIRED' });
      const seed = newId();
      patch.seed = seed;
      Object.assign(patch, (({ groups, unsatisfied }) => ({ groupsJson: groups, unsatisfiedJson: unsatisfied }))(generateGroups(ctx, context, mode, sizing, seed, row.groupsJson)));
    }
    return saveTemplate(
      ctx,
      row,
      patch,
      'grouping.template_update',
      { name: row.name, mode: row.mode, sizing: row.sizingJson, groups: row.groupsJson.map((g) => ({ name: g.name, memberIds: g.memberIds, roles: g.roles.length })) },
      { name: patch.name ?? row.name, mode, sizing, groups: (patch.groupsJson ?? row.groupsJson).map((g) => ({ name: g.name, memberIds: g.memberIds, roles: g.roles.length })) },
    );
  });
}

export function archiveTemplate(ctx: RequestContext, input: In<typeof C.archiveGroupTemplate>): GroupTemplate {
  return tx(ctx.db, () => {
    const { row } = ownedTemplate(ctx, input.templateId, true);
    const archivedAt = input.archived ? (row.archivedAt ?? ctx.now()) : null;
    return saveTemplate(ctx, row, { archivedAt }, input.archived ? 'grouping.template_archive' : 'grouping.template_restore', { archived: row.archivedAt !== null }, { archived: input.archived });
  });
}

// ---------------------------------------------------------------- pair rules (GRP-4, private)
export function createRule(ctx: RequestContext, input: In<typeof C.createPairRule>): PairRule {
  return tx(ctx.db, () => {
    const context = assertOwnsContext(ctx, input.contextId);
    const cls = getClass(ctx.db, context.classId);
    assertClassWritable(ctx.db, cls);
    assertModuleEnabled(ctx.db, context.id, 'grouping');
    if (input.studentA === input.studentB) throw new AppError('VALIDATION', 'Choose two different students', { reason: 'SAME_STUDENT' });
    const roster = new Set(rosterOn(ctx.db, cls, todayFor(ctx, cls)).map((s) => s.id));
    if (!roster.has(input.studentA) || !roster.has(input.studentB)) throw new AppError('FORBIDDEN', 'Student is not in this class', { reason: 'STUDENT_NOT_IN_CLASS' });
    const [a, b] = input.studentA < input.studentB ? [input.studentA, input.studentB] : [input.studentB, input.studentA];
    const existing = ctx.db
      .select()
      .from(pairConstraints)
      .where(and(eq(pairConstraints.contextId, context.id), eq(pairConstraints.studentA, a), eq(pairConstraints.studentB, b), isNull(pairConstraints.archivedAt)))
      .get();
    if (existing) throw new AppError('CONFLICT', 'There is already a rule for these two students', { reason: 'RULE_EXISTS', ruleId: existing.id });
    const now = ctx.now();
    const id = newId();
    const note = input.note?.trim() || null;
    ctx.db.insert(pairConstraints).values({ id, contextId: context.id, studentA: a, studentB: b, kind: input.kind, note, archivedAt: null, createdAt: now, createdBy: requireUser(ctx).id, updatedAt: now }).run();
    audit(ctx.db, ctx.actor, { action: 'grouping.rule_create', entity: 'pair_constraint', entityId: id, after: { studentA: a, studentB: b, kind: input.kind, hasNote: Boolean(note) } }, now);
    return toRule(ctx.db.select().from(pairConstraints).where(eq(pairConstraints.id, id)).get()!);
  });
}

function ownedRule(ctx: RequestContext, ruleId: string) {
  const row = ctx.db.select().from(pairConstraints).where(eq(pairConstraints.id, ruleId)).get();
  if (!row || row.archivedAt !== null) throw notFound('Rule');
  const context = assertOwnsContext(ctx, row.contextId);
  assertClassWritable(ctx.db, getClass(ctx.db, context.classId));
  assertModuleEnabled(ctx.db, context.id, 'grouping');
  return row;
}

export function updateRule(ctx: RequestContext, input: In<typeof C.updatePairRule>): PairRule {
  return tx(ctx.db, () => {
    const row = ownedRule(ctx, input.ruleId);
    const now = ctx.now();
    const next = { kind: input.kind ?? row.kind, note: input.note === undefined ? row.note : input.note?.trim() || null };
    ctx.db.update(pairConstraints).set({ ...next, updatedAt: now }).where(eq(pairConstraints.id, row.id)).run();
    audit(ctx.db, ctx.actor, { action: 'grouping.rule_update', entity: 'pair_constraint', entityId: row.id, before: { kind: row.kind, hasNote: Boolean(row.note) }, after: { kind: next.kind, hasNote: Boolean(next.note) } }, now);
    return toRule(ctx.db.select().from(pairConstraints).where(eq(pairConstraints.id, row.id)).get()!);
  });
}

export function removeRule(ctx: RequestContext, ruleId: string) {
  return tx(ctx.db, () => {
    const row = ownedRule(ctx, ruleId);
    const now = ctx.now();
    ctx.db.update(pairConstraints).set({ archivedAt: now, updatedAt: now }).where(eq(pairConstraints.id, row.id)).run();
    audit(ctx.db, ctx.actor, { action: 'grouping.rule_archive', entity: 'pair_constraint', entityId: row.id, before: { kind: row.kind } }, now);
    return { ok: true as const };
  });
}

// ---------------------------------------------------------------- classroom (display-safe)
export function classroomArrangements(ctx: RequestContext, contextId: string) {
  const context = assertOwnsContext(ctx, contextId);
  assertModuleEnabled(ctx.db, context.id, 'grouping');
  ensureDefaultArrangements(ctx, context);
  return { arrangements: templateRows(ctx.db, context.id, false).map((r) => ({ id: r.id, name: r.name, icon: (r.icon as GroupTemplate['icon']) ?? null, groupCount: r.groupsJson.filter((g) => g.memberIds.length > 0).length })) };
}

/** Students away for this lesson (effective attendance absent / excused). Empty with Attendance off. */
function awayIn(db: Db, lesson: LessonRow): Set<string> {
  if (!isModuleEnabled(db, lesson.contextId, 'attendance')) return new Set();
  const daily = dailyFor(db, lesson.classId, lesson.localDate);
  const exc = exceptionsFor(db, lesson.id);
  const out = new Set<string>();
  for (const { student } of rosterRowsOn(db, lesson.classId, lesson.localDate)) {
    if (isAway(effectiveAttendance(exc.get(student.id)?.status ?? null, daily.get(student.id)?.status ?? null))) out.add(student.id);
  }
  return out;
}

const liveGrouping = (db: Db, lessonId: string) => db.select().from(lessonGroupings).where(and(eq(lessonGroupings.lessonId, lessonId), isNull(lessonGroupings.clearedAt))).get();

/**
 * 'grouping.apply' (GRP-5, UX-8): copy the arrangement into the lesson, fitted to the students who
 * are not absent or excused. The saved arrangement is not modified. Id = opId (replays are harmless).
 */
export function applyGrouping(ctx: RequestContext, p: z.infer<(typeof C.GroupingCommands)['grouping.apply']>, meta: CommandMeta) {
  const { context, lesson } = lessonForCommand(ctx, p, meta);
  assertModuleEnabled(ctx.db, context.id, 'grouping');
  const tpl = ctx.db.select().from(groupTemplates).where(eq(groupTemplates.id, p.templateId)).get();
  if (!tpl || tpl.contextId !== context.id || tpl.archivedAt !== null) throw new AppError('NOT_FOUND', 'Arrangement not found', { reason: 'ARRANGEMENT_NOT_FOUND' });
  const roster = rosterRowsOn(ctx.db, lesson.classId, lesson.localDate).map((r) => r.student.id);
  const away = awayIn(ctx.db, lesson);
  const present = roster.filter((id) => !away.has(id));
  const rules = domainRules(ruleRows(ctx.db, context.id));
  let groups: GroupJson[];
  let unsatisfied: UnsatisfiedJson[];
  if (!tpl.groupsJson.some((g) => g.memberIds.length > 0) && present.length) {
    // Nothing saved to fit (made before the class had students): make groups for this lesson from
    // the arrangement's type and size, without changing the arrangement (GRP-5).
    const here = new Set(present);
    const rows = rosterRowsOn(ctx.db, lesson.classId, lesson.localDate)
      .map((r) => r.student)
      .filter((st) => here.has(st.id));
    ({ groups, unsatisfied } = generateFor(ctx.db, context, rows, tpl.mode === 'custom' ? 'mixed' : tpl.mode, tpl.sizingJson, `${tpl.seed}:${lesson.id}`, tpl.groupsJson));
  } else {
    // Target-size arrangements also merge groups left too small by absences (no "pair" of one).
    const fitted = fitToPresent(
      tpl.groupsJson.map((g) => g.memberIds),
      present,
      rules,
      `${tpl.seed}:${lesson.id}`,
      tpl.sizingJson,
    );
    groups = fitted.groups
      .map((memberIds, i) => {
        const saved = tpl.groupsJson[i];
        const d = defaultName(i);
        const members = new Set(memberIds);
        return { id: saved?.id ?? `extra-${i}`, name: saved?.name ?? { ...d.name }, icon: saved?.icon ?? d.icon, memberIds, roles: (saved?.roles ?? []).filter((r) => members.has(r.studentId)) };
      })
      .filter((g) => g.memberIds.length > 0);
    unsatisfied = evaluateRules(groups.map((g) => g.memberIds), rules, { byHand: tpl.mode === 'custom' }) as UnsatisfiedJson[];
  }
  const excluded = roster.filter((id) => away.has(id));
  const now = ctx.now();
  ctx.db.update(lessonGroupings).set({ clearedAt: now }).where(and(eq(lessonGroupings.lessonId, lesson.id), isNull(lessonGroupings.clearedAt))).run();
  ctx.db
    .insert(lessonGroupings)
    .values({ id: meta.opId, lessonId: lesson.id, contextId: context.id, templateId: tpl.id, templateVersion: tpl.version, effectiveGroupsJson: groups, excludedAbsentIds: excluded, unsatisfiedJson: unsatisfied, appliedAt: now, appliedBy: requireUser(ctx).id, clearedAt: null })
    .run();
  updateLesson(ctx, lesson, {});
  audit(ctx.db, ctx.actor, { action: 'grouping.apply', entity: 'lesson', entityId: lesson.id, opId: meta.opId, after: { templateId: tpl.id, templateVersion: tpl.version, groups: groups.length, excluded: excluded.length, unsatisfied: unsatisfied.length } }, now);
  return { groupingId: meta.opId, groups: groups.length, excludedCount: excluded.length };
}

/** The live grouping of the lesson or a GROUPS_NOT_SHOWN refusal (S13a commands need groups on the display). */
function requireLive(db: Db, lessonId: string) {
  const live = liveGrouping(db, lessonId);
  if (!live) throw new AppError('CONFLICT', 'No groups are shown in this lesson', { reason: 'GROUPS_NOT_SHOWN' });
  return live;
}

function presentStudents(db: Db, lesson: LessonRow) {
  const away = awayIn(db, lesson);
  return rosterRowsOn(db, lesson.classId, lesson.localDate)
    .map((r) => r.student)
    .filter((st) => !away.has(st.id));
}

function insertLessonGrouping(ctx: RequestContext, lesson: LessonRow, tpl: TemplateRow, id: string, groups: GroupJson[], unsatisfied: UnsatisfiedJson[]) {
  const away = awayIn(ctx.db, lesson);
  const roster = rosterRowsOn(ctx.db, lesson.classId, lesson.localDate).map((r) => r.student.id);
  const now = ctx.now();
  ctx.db.update(lessonGroupings).set({ clearedAt: now }).where(and(eq(lessonGroupings.lessonId, lesson.id), isNull(lessonGroupings.clearedAt))).run();
  ctx.db
    .insert(lessonGroupings)
    .values({ id, lessonId: lesson.id, contextId: lesson.contextId, templateId: tpl.id, templateVersion: tpl.version, effectiveGroupsJson: groups, excludedAbsentIds: roster.filter((x) => away.has(x)), unsatisfiedJson: unsatisfied, appliedAt: now, appliedBy: requireUser(ctx).id, clearedAt: null })
    .run();
}

/**
 * 'grouping.shuffle' (S13a): new groups for the option in use from a new seed, for the students present
 * now; the saved option is not changed. The previous grouping stays in the history so 'grouping.restore'
 * can undo the shuffle. Id = opId; the seed is derived from it, so a replay is harmless.
 */
export function shuffleGrouping(ctx: RequestContext, p: z.infer<(typeof C.GroupingCommands)['grouping.shuffle']>, meta: CommandMeta) {
  const { context, lesson } = lessonForCommand(ctx, p, meta);
  assertModuleEnabled(ctx.db, context.id, 'grouping');
  const live = requireLive(ctx.db, lesson.id);
  const tpl = ctx.db.select().from(groupTemplates).where(eq(groupTemplates.id, live.templateId)).get();
  if (!tpl) throw new AppError('NOT_FOUND', 'Arrangement not found', { reason: 'ARRANGEMENT_NOT_FOUND' });
  const mode = tpl.mode === 'custom' ? 'mixed' : tpl.mode;
  const sizing: Sizing = tpl.mode === 'custom' ? { groupCount: Math.max(1, tpl.groupsJson.filter((g) => g.memberIds.length).length) } : tpl.sizingJson;
  const { groups, unsatisfied } = generateFor(ctx.db, context, presentStudents(ctx.db, lesson), mode, sizing, `shuffle:${meta.opId}`, tpl.groupsJson);
  const kept = groups.filter((g) => g.memberIds.length > 0);
  insertLessonGrouping(ctx, lesson, tpl, meta.opId, kept, unsatisfied);
  updateLesson(ctx, lesson, {});
  audit(ctx.db, ctx.actor, { action: 'grouping.shuffle', entity: 'lesson', entityId: lesson.id, opId: meta.opId, before: { groupingId: live.id }, after: { templateId: tpl.id, groups: kept.length } }, ctx.now());
  return { groupingId: meta.opId, previousId: live.id };
}

/** 'grouping.restore' (S13a): show an earlier grouping of this lesson again (undo of Shuffle). */
export function restoreGrouping(ctx: RequestContext, p: z.infer<(typeof C.GroupingCommands)['grouping.restore']>, meta: CommandMeta) {
  const { context, lesson } = lessonForCommand(ctx, p, meta);
  assertModuleEnabled(ctx.db, context.id, 'grouping');
  const row = ctx.db.select().from(lessonGroupings).where(eq(lessonGroupings.id, p.groupingId)).get();
  if (!row || row.lessonId !== lesson.id) throw new AppError('NOT_FOUND', 'Grouping not found', { reason: 'GROUPING_NOT_FOUND' });
  if (row.clearedAt === null) return { groupingId: row.id, restored: false };
  const now = ctx.now();
  ctx.db.update(lessonGroupings).set({ clearedAt: now }).where(and(eq(lessonGroupings.lessonId, lesson.id), isNull(lessonGroupings.clearedAt))).run();
  ctx.db.update(lessonGroupings).set({ clearedAt: null }).where(eq(lessonGroupings.id, row.id)).run();
  updateLesson(ctx, lesson, {});
  audit(ctx.db, ctx.actor, { action: 'grouping.restore', entity: 'lesson', entityId: lesson.id, opId: meta.opId, after: { groupingId: row.id } }, now);
  return { groupingId: row.id, restored: true };
}

/**
 * 'grouping.move' (S13a): one student into another group of the lesson's groups (tap a student, tap a
 * group; or drag). Only students of the class who are here now; a student in no group yet (a late
 * arrival) is placed. Applies to this lesson at once; 'grouping.saveToOption' keeps it for later.
 */
export function moveInGrouping(ctx: RequestContext, p: z.infer<(typeof C.GroupingCommands)['grouping.move']>, meta: CommandMeta) {
  const { context, lesson } = lessonForCommand(ctx, p, meta);
  assertModuleEnabled(ctx.db, context.id, 'grouping');
  const live = requireLive(ctx.db, lesson.id);
  if (!presentStudents(ctx.db, lesson).some((st) => st.id === p.studentId)) throw new AppError('CONFLICT', 'This student is not here in this lesson', { reason: 'STUDENT_NOT_PRESENT' });
  const groups = live.effectiveGroupsJson;
  if (!groups.some((g) => g.id === p.toGroupId)) throw new AppError('NOT_FOUND', 'Group not found', { reason: 'GROUP_NOT_FOUND' });
  const from = groups.find((g) => g.memberIds.includes(p.studentId))?.id ?? null;
  if (from === p.toGroupId) return { moved: false, from };
  const next = groups.map((g) => ({
    ...g,
    memberIds: g.id === p.toGroupId ? [...g.memberIds.filter((x) => x !== p.studentId), p.studentId] : g.memberIds.filter((x) => x !== p.studentId),
    roles: g.id === p.toGroupId ? g.roles : g.roles.filter((r) => r.studentId !== p.studentId),
  }));
  const unsatisfied = evaluateRules(next.map((g) => g.memberIds), domainRules(ruleRows(ctx.db, context.id)), { byHand: true }) as UnsatisfiedJson[];
  ctx.db.update(lessonGroupings).set({ effectiveGroupsJson: next, unsatisfiedJson: unsatisfied }).where(eq(lessonGroupings.id, live.id)).run();
  updateLesson(ctx, lesson, {});
  audit(ctx.db, ctx.actor, { action: 'grouping.move', entity: 'lesson', entityId: lesson.id, opId: meta.opId, after: { groupingId: live.id, studentId: p.studentId, from, to: p.toGroupId } }, ctx.now());
  return { moved: true, from };
}

/**
 * 'grouping.saveToOption' (S13a): the lesson's groups become the option's saved groups. Students away
 * in this lesson keep the group they had in the option; groups made only for the lesson are added.
 * Bumps the option's version (audited); the option keeps its type, so Shuffle still works.
 */
export function saveGroupingToOption(ctx: RequestContext, p: z.infer<(typeof C.GroupingCommands)['grouping.saveToOption']>, meta: CommandMeta) {
  const { context, lesson } = lessonForCommand(ctx, p, meta);
  assertModuleEnabled(ctx.db, context.id, 'grouping');
  assertClassWritable(ctx.db, getClass(ctx.db, context.classId));
  const live = requireLive(ctx.db, lesson.id);
  const tpl = ctx.db.select().from(groupTemplates).where(eq(groupTemplates.id, live.templateId)).get();
  if (!tpl || tpl.archivedAt !== null) throw new AppError('NOT_FOUND', 'Arrangement not found', { reason: 'ARRANGEMENT_NOT_FOUND' });
  const inLesson = new Set(live.effectiveGroupsJson.flatMap((g) => g.memberIds));
  const saved: GroupJson[] = tpl.groupsJson.map((g) => {
    const lessonGroup = live.effectiveGroupsJson.find((x) => x.id === g.id);
    const keep = g.memberIds.filter((x) => !inLesson.has(x));
    const members = [...(lessonGroup?.memberIds ?? []), ...keep];
    const set = new Set(members);
    return { ...g, memberIds: members, roles: [...(lessonGroup?.roles ?? []), ...g.roles.filter((r) => keep.includes(r.studentId))].filter((r) => set.has(r.studentId)) };
  });
  for (const g of live.effectiveGroupsJson) if (!tpl.groupsJson.some((x) => x.id === g.id)) saved.push({ ...g, id: newId() });
  const unsatisfied = evaluateRules(saved.map((g) => g.memberIds), domainRules(ruleRows(ctx.db, context.id)), { byHand: true }) as UnsatisfiedJson[];
  const now = ctx.now();
  ctx.db.update(groupTemplates).set({ groupsJson: saved, unsatisfiedJson: unsatisfied, version: tpl.version + 1, updatedAt: now, updatedBy: requireUser(ctx).id }).where(eq(groupTemplates.id, tpl.id)).run();
  audit(ctx.db, ctx.actor, { action: 'grouping.save_to_option', entity: 'group_template', entityId: tpl.id, opId: meta.opId, before: { version: tpl.version, groups: tpl.groupsJson.map((g) => g.memberIds) }, after: { groups: saved.map((g) => g.memberIds) } }, now);
  updateLesson(ctx, lesson, {});
  return { templateId: tpl.id, version: tpl.version + 1 };
}

export function clearGrouping(ctx: RequestContext, p: z.infer<(typeof C.GroupingCommands)['grouping.clear']>, meta: CommandMeta) {
  const { context, lesson } = lessonForCommand(ctx, p, meta);
  assertModuleEnabled(ctx.db, context.id, 'grouping');
  const live = liveGrouping(ctx.db, lesson.id);
  if (!live) return { cleared: false };
  const now = ctx.now();
  ctx.db.update(lessonGroupings).set({ clearedAt: now }).where(eq(lessonGroupings.id, live.id)).run();
  updateLesson(ctx, lesson, {});
  audit(ctx.db, ctx.actor, { action: 'grouping.clear', entity: 'lesson', entityId: lesson.id, opId: meta.opId, before: { groupingId: live.id } }, now);
  return { cleared: true };
}

/**
 * Polled lesson state (DSH-8): classroom-safe groups; students marked away since are left out too.
 * The counts follow current attendance: `excludedCount` = students of the class away now,
 * `notPlacedCount` = students here now who are in no group (a late arrival, a new student) until the
 * teacher chooses the groups again.
 */
export function groupingLessonState(db: Db, lesson: LessonRow): GroupingLessonState {
  const live = liveGrouping(db, lesson.id);
  const upperCaseNames = moduleConfig(db, lesson.contextId, 'grouping').upperCaseNames === true;
  if (!live) return { applied: false, arrangementId: null, groupingId: null, upperCaseNames, notPlaced: [], groups: [], excludedCount: 0, notPlacedCount: 0 };
  const away = awayIn(db, lesson);
  const ids = [...new Set(live.effectiveGroupsJson.flatMap((g) => g.memberIds))];
  const byId = new Map((ids.length ? db.select().from(students).where(inArray(students.id, ids)).all() : []).map((s) => [s.id, s]));
  const inGroup = new Set(ids);
  const rosterRows = rosterRowsOn(db, lesson.classId, lesson.localDate).map((r) => r.student);
  const roster = rosterRows.map((st) => st.id);
  return {
    applied: true,
    arrangementId: live.templateId,
    groupingId: live.id,
    upperCaseNames,
    notPlaced: rosterRows.filter((st) => !away.has(st.id) && !inGroup.has(st.id)).map((st) => ({ id: st.id, fullName: st.fullName, initials: initials(st.fullName), avatarHue: st.avatarHue })),
    groups: live.effectiveGroupsJson.map((g) => ({
      id: g.id,
      name: g.name,
      icon: g.icon,
      members: g.memberIds
        .filter((id) => !away.has(id) && byId.has(id))
        .map((id) => {
          const s = byId.get(id)!;
          const role = g.roles.find((r) => r.studentId === id)?.label ?? null;
          return { id: s.id, fullName: s.fullName, initials: initials(s.fullName), avatarHue: s.avatarHue, role };
        }),
    })),
    excludedCount: roster.filter((id) => away.has(id)).length,
    notPlacedCount: roster.filter((id) => !away.has(id) && !inGroup.has(id)).length,
  };
}

export const groupingStamp = (db: Db, lesson: LessonRow | null) => (lesson ? `g${liveGrouping(db, lesson.id)?.id ?? 'none'}` : 'g-');

// ---------------------------------------------------------------- reports hook (S11)
/**
 * RPT-1 "grouping history" (RPT-5, counts only): `lessonsWithGroups` = distinct lessons of the period
 * in which groups were shown; per arrangement, `lessons` = distinct lessons in which it was shown.
 * Applying it again in the same lesson (e.g. after a late arrival) does not count twice; a lesson that
 * switched arrangements counts once for each arrangement shown.
 */
export function groupingReport(ctx: RequestContext, q: { contextId: string; from: string; to: string }) {
  const rows = ctx.db
    .select({ templateId: lessonGroupings.templateId, lessonId: lessonGroupings.lessonId, localDate: lessons.localDate })
    .from(lessonGroupings)
    .innerJoin(lessons, eq(lessons.id, lessonGroupings.lessonId))
    .where(and(eq(lessonGroupings.contextId, q.contextId), gte(lessons.localDate, q.from), lte(lessons.localDate, q.to)))
    .all();
  const uses = new Map<string, Set<string>>();
  for (const r of rows) uses.set(r.templateId, (uses.get(r.templateId) ?? new Set<string>()).add(r.lessonId));
  return { lessonsWithGroups: new Set(rows.map((r) => r.lessonId)).size, arrangementsUsed: [...uses].map(([templateId, ls]) => ({ templateId, lessons: ls.size })) };
}
